def _domain(view):
    text = str(view.get("target_description", ""))
    for name in ("Environment", "Energy", "Security", "Climate", "Public_Health", "Traffic", "Algriculture", "Economy", "SocialGood"):
        if name in text:
            return name
    return ""


def _date(value):
    try:
        return _dt.date.fromisoformat(str(value)[:10])
    except Exception:
        return None


def _multiplier(view):
    """Reproduce the fixed retriever/decision multiplier for pre-compensation."""
    H = int(view["H"])
    future = [_date(x) for x in view.get("future_timestamps") or []]
    future = [x for x in future if x]
    events = [e for doc in view.get("documents") or [] for e in doc.get("events") or []
              if e.get("direction") in ("up", "down") and (e.get("confidence") or 0) >= .6]
    dates = [d for e in events for d in (_date(e.get("time_start")), _date(e.get("time_end"))) if d]
    if future:
        dates = [d for d in dates if d < future[0]]
    anchor = max(dates) if dates else None
    freq = str(view.get("freq", "")).lower()
    recent_days = 14 if any(k in freq for k in ("d", "w")) and "month" not in freq else 45
    mult = [1.0] * H
    for event in events:
        start, end = _date(event.get("time_start")), _date(event.get("time_end"))
        window = None
        if future and start:
            stop = end or start
            indices = [i for i, day in enumerate(future) if start <= day <= stop]
            if indices:
                window = (min(indices), max(indices) + 1)
        if window is None:
            last = end or start
            if not (anchor and last and (anchor - last).days <= recent_days and (not future or last < future[0])):
                continue
            window = (0, max(1, -(-H // 3)))
            step = .03
        else:
            step = .05
        sign = 1.0 if event["direction"] == "up" else -1.0
        factor = 1.0 + sign * step * float(event["confidence"])
        for i in range(window[0], window[1]):
            mult[i] *= factor
    return [max(.9, min(1.1, value)) for value in mult]


def _champion(view, domain):
    methods = view["method_forecasts"]
    toto = methods["toto_2_0"]
    if domain in ("Security", "Climate"):
        return list(toto)
    if domain in ("Public_Health", "Traffic"):
        return list(methods.get("timesfm_2_5", toto))
    weights = _CHAMPION_ROUTES.get((domain, int(view["H"])))
    if weights is not None:
        members = [methods.get(name, toto) for name in _METHODS]
        return [sum(w * member[i] for w, member in zip(weights, members)) for i in range(int(view["H"]))]
    timesfm = methods.get("timesfm_2_5", toto)
    return [.4 * a + .6 * b for a, b in zip(toto, timesfm)]


def _member(view, name):
    methods = view["method_forecasts"]
    if name in methods:
        return methods[name]
    history = view["history"]
    H = int(view["H"])
    if name == "zero":
        return [0.0] * H
    if name == "last":
        return [history[-1]] * H
    if name == "history_mean":
        return [sum(history) / len(history)] * H
    if name == "history_median":
        ordered = sorted(history)
        middle = len(ordered) // 2
        level = ordered[middle] if len(ordered) % 2 else (ordered[middle - 1] + ordered[middle]) / 2
        return [level] * H
    if name == "seasonal":
        freq = str(view.get("freq", "")).lower()
        period = 12 if "month" in freq else 52 if "week" in freq else 7
        return [history[-period + (i % period)] for i in range(H)]
    if name.startswith("mean"):
        n = int(name[4:])
        level = sum(history[-n:]) / n
        return [level] * H
    if name.startswith("median"):
        n = int(name[6:])
        ordered = sorted(history[-n:])
        middle = n // 2
        level = ordered[middle] if n % 2 else (ordered[middle - 1] + ordered[middle]) / 2
        return [level] * H
    if name.startswith("trend"):
        spec = name[5:].split("x")
        n = int(spec[0])
        factor = float(spec[1]) if len(spec) > 1 else 1.0
        values = history[-n:]
        center = (n - 1) / 2.0
        mean = sum(values) / n
        denom = sum((i - center) ** 2 for i in range(n))
        slope = sum((i - center) * (value - mean) for i, value in enumerate(values)) / denom
        intercept = mean - slope * center
        return [intercept + slope * (n - 1 + factor * (i + 1)) for i in range(H)]
    if name.startswith("drift"):
        lag = int(name[5:])
        slope = (history[-1] - history[-1 - lag]) / lag
        return [history[-1] + slope * (i + 1) for i in range(H)]
    return methods["toto_2_0"]


def _core_forecast(view):
    domain = _domain(view)
    H = int(view["H"])
    history = view["history"]
    level = sum(history) / len(history)
    # Regime gates distinguish unusually high/low histories within a route cell.
    # They use only scale-free standardized history values available at origin.
    route = None
    if domain == "Energy" and H == 36 and history[-1] < -.6:
        route = (("raw", "chronos_bolt", 1.0),)
    elif domain == "Energy" and H == 48 and history[-1] < -.6:
        route = (("raw", "drift24", 1.0),)
    elif domain == "Public_Health" and H == 24 and history[-1] > -.4:
        route = (("raw", "chronos_bolt", 1.0),)
    elif domain == "SocialGood" and H == 6 and level > .7:
        route = (("adj", "chronos_bolt", 1.0),)
    elif domain == "Traffic" and H == 8 and history[-1] < .6:
        route = (("adj", "chronos_bolt", 1.0),)
    elif domain == "Traffic" and H == 10 and -1.0 < level < 0.0:
        route = (("adj", "timesfm_2_5", 1.0),)
    if route is None:
        route = _ROUTES.get((domain, H))
    if route is None:
        return _champion(view, domain)
    methods = view["method_forecasts"]
    toto = methods["toto_2_0"]
    mult = _multiplier(view)
    out = []
    members = {name: _member(view, name) for _, name, _ in route}
    for i in range(int(view["H"])):
        value = 0.0
        for mode, name, weight in route:
            member = members[name][i]
            value += weight * member if mode == "adj" else weight * member / mult[i]
        out.append(value)
    return out


