def _legendre_values(x, degree):
    values = [1.0]
    if degree == 0:
        return values
    values.append(x)
    for n in range(2, degree + 1):
        values.append(((2 * n - 1) * x * values[-1] - (n - 1) * values[-2]) / n)
    return values


def forecast(view):
    base = _core_forecast(view)
    entry = _REGIMES.get((_domain(view), int(view["H"])))
    if entry is None:
        return base
    thresholds, choices = entry
    level = view["history"][-1]
    index = 0
    while index < len(thresholds) and level > thresholds[index]:
        index += 1
    coef = choices[index]
    H = int(view["H"])
    mult = _multiplier(view)
    final = [base[i] * mult[i] for i in range(H)]
    calibrated = []
    for i, value in enumerate(final):
        x = 2.0 * (i + 1.0) / H - 1.0
        residual = sum(weight * basis for weight, basis in zip(coef, _legendre_values(x, len(coef) - 1)))
        calibrated.append((value + residual) / mult[i])
    return calibrated



