_SMOOTH_FORECAST = forecast


def forecast(view):
    base = _SMOOTH_FORECAST(view)
    entry = _STEP_RESIDUALS.get((_domain(view), int(view["H"])))
    if entry is None:
        return base
    thresholds, choices = entry
    level = view["history"][-1]
    index = 0
    while index < len(thresholds) and level > thresholds[index]:
        index += 1
    residual = choices[index]
    mult = _multiplier(view)
    return [(base[i] * mult[i] + residual[i]) / mult[i]
            for i in range(int(view["H"]))]
